import fs from 'node:fs/promises';
const d='data/research/short-squeeze-sell-pressure-20261107',x=JSON.parse(await fs.readFile(d+'/results.json')),fmt=(n,d=2)=>Number.isFinite(n)?n.toFixed(d):'—',pct=n=>fmt(n)+'%',sweep=s=>s.swept+'/'+s.model.n+' · '+pct(s.model.sweepPct),ci=a=>a?.map(n=>fmt(n)).join(' → ')??'—';
let md='# SHORT ép LONG: tăng ngưỡng lực bán chủ động\n\nVersion '+x.protocol.version+'. Dùng nguyên318cảnh báo và kết quả đã đóng băng ở nghiên cứu SHORT_SQUEEZE_VOLUME_ACTUAL_V1_20261107, cutoff07/11/2026 20:45VN. Đây là phân nhóm lại trên mẫu đã xem, không phải lần kiểm định bằng dữ liệu mới.\n\n';
md+='## Nhận xét\n\nTăng ngưỡng không làm kết quả tốt lên đều. Ngưỡng55% có123tín hiệu, win71,54%, ROE TB+1,46%. Tăng60% hoặc65% làm ROE TB giảm lần lượt còn+1,33% và+1,29%. Mức70% giữ30tín hiệu, win73,33%, ROE TB+2,27%, quét11/28cụm dưới (39,29%). Tăng tiếp75%/80% lại giảm ROE và tỷ lệ thắng, đồng thời mẫu còn13/7.\n\n70% là ứng viên đáng theo dõi, chưa được gọi là ngưỡng tối ưu. So với55%, chênh ROE TB+0,81điểm%, CI95% theo coin −0,44→+2,16điểm%, còn chứa0. Đây là nghiên cứu thêm nhiều ngưỡng sau khi đã thấy55% đẹp, không có holdout mới. Mẫu trưởng thành chỉ trải từ06/11 23:41 đến07/11 12:39VN; biến động cùng phiên có thể ảnh hưởng nhiều coin cùng lúc.\n\nTăng55→70 giữ30/123=24,39% tín hiệu.93tín hiệu bị loại vẫn có ROE TB+1,19%; ROE mỗi lệnh cao hơn không tự bảo đảm tổng hiệu quả vốn tốt hơn. Chưa thay ngưỡng bot hoặc Discord.\n\n';
md+='## So các ngưỡng lồng nhau\n\n| Lực bán15m | Mẫu | Win net | ROE TB | ROE stress | Quét hết cụm / mẫu có cụm |\n|---|---:|---:|---:|---:|---:|\n'+Object.entries(x.groups).map(([t,g])=>{const s=g.all;return'| ≥'+t+'% | '+s.n+' | '+pct(s.winPct)+' | '+pct(s.meanRoe)+' | '+pct(s.stressMeanRoe)+' | '+sweep(s)+' |';}).join('\n')+'\n\nMẫu số quét chỉ gồm cụm Model1/3 đủ điều kiện và chưa chạm trước entry. Quét được đo riêng trong8h, có thể xảy ra sauSL; không đồng nhất với giao dịch thắng.\n\n';
md+='## Các khoảng rời nhau\n\n| Lực bán15m | Mẫu | Win net | ROE TB | Quét hết cụm |\n|---|---:|---:|---:|---:|\n'+Object.entries(x.bins).map(([k,s])=>'| '+k+'% | '+s.n+' | '+pct(s.winPct)+' | '+pct(s.meanRoe)+' | '+sweep(s)+' |').join('\n')+'\n\nNhóm70–75% có17mẫu, ROE TB+3,08%/win82,35%, giúp ngưỡng≥70 trông tốt. Chọn riêng khoảng này sau khi xem kết quả sẽ tăng nguy cơ khớp quá mức với mẫu cũ. Các nhóm≥80% quá ít để suy quy luật về áp lực bán cực cao.\n\n';
md+='## Kiểm tra theo thời điểm\n\n| Ngưỡng | Phần trước: n / ROE TB | Phần cuối: n / ROE TB |\n|---|---:|---:|\n'+Object.entries(x.groups).map(([t,g])=>'| ≥'+t+'% | '+g.earlier.n+' / '+pct(g.earlier.meanRoe)+' | '+g.later.n+' / '+pct(g.later.meanRoe)+' |').join('\n')+'\n\nNguồn chia70/30 nhưng khi purge toàn bộ8h tương lai trước mốc, TRAIN=0;222tín hiệu phần trước và96phần cuối chỉ là đối chiếu mô tả, không phải hai tập học/kiểm định độc lập. Tập cuối có thị trường thuận lợi choSHORT ở nhiều coin, không lấy riêng kết quả phần cuối làm xác nhận.\n\n';
md+='## Nếu vẫn yêu cầu volume tăng\n\n| Ngưỡng bán | Volume≥1×: n / ROE TB | Volume≥1,5×: n / ROE TB |\n|---|---:|---:|\n'+Object.entries(x.groups).map(([t,g])=>'| ≥'+t+'% | '+g.relativeVolume1.n+' / '+pct(g.relativeVolume1.meanRoe)+' | '+g.relativeVolume1_5.n+' / '+pct(g.relativeVolume1_5.meanRoe)+' |').join('\n')+'\n\nMức70% kết hợp volume≥1× chỉ còn7mẫu, ROE TB−0,03%. Chưa thấy căn cứ thêm đồng thời ngưỡng volume chỉ vì ngưỡng áp lực bán đơn lẻ có kết quả đẹp. Đây là giao điều kiện cố định để đối chiếu, không tối ưu lại.\n\n';
md+='## Độ chắc chắn khi tăng so với55%\n\nBootstrap2.000lần theo coin và khối2h; chênh lệch ROE TB của nhóm ngưỡng cao trừ cùng nhóm55%. Các khoảng95% danh nghĩa chưa điều chỉnh thử nhiều ngưỡng.\n\n| Ngưỡng | Mẫu | Δ ROE CI theo coin (điểm%) | Δ ROE CI theo khối2h (điểm%) |\n|---|---:|---:|---:|\n'+[60,65,70].map(t=>'| ≥'+t+'% | '+x.groups[t].all.n+' | '+ci(x.uncertainty[t].byCoin.roe.delta95)+' | '+ci(x.uncertainty[t].by2h.roe.delta95)+' |').join('\n')+'\n\nChỉ7khối2h và nhiều mẫu có cùng bối cảnh thị trường; CI không loại bỏ mọi phụ thuộc. Từ75% trở lên chỉ13mẫu hoặc ít hơn, không diễn giải bootstrap thành bằng chứng thắng/thua; đặc biệt90% chỉ1mẫu, bootstrap không thể biết biến thiên của các trường hợp chưa quan sát. Chi tiết tính toán vẫn lưu trong JSON để kiểm tra.\n\n';
md+='## Phương pháp, dữ liệu và kiểm tra\n\nGiữ nguyên318cảnh báo SENT đủ8h của nhánh CrowdLONG≥60%, cá voi và Smart cùng giảm tỷ trọngLONG4h. Tổng nhật ký gốc500,182pending không được thêm vào nghiên cứu này. Không thay universe, điểm vào, TP/SL, phí/funding hoặc cooldown theo ngưỡng.\n\nLực bán =100×(quoteVolume−takerBuyQuoteVolume)/quoteVolume của3nến5m đã đóng trước cảnh báo. Đó là tỷ trọng khối lượng USDT bán chủ động trong15phút, không phải tỷ lệ tài khoảnSHORT, cũng không phải tỷ trọng cá voiSHORT. Volume nền giữ nguyên định nghĩa20nến5m quy ra15phút.\n\nMô phỏngSHORT3×,TP10%/SL20% grossROE,max8h, chi phí hai chiều0,14%notional+funding,stress0,30%; cùng nến ưu tiênSL, gap bất lợi theoopen. Quét=MARK đi hết mépdưới cụm chungModel1/3 chốttrước giá,36h432nến/OI≥95%/lag5m; đây là ước lượng, không xác nhận thanh lý thật. ROE dương lànetwin, không phải chỉ chạmTP. Các mô phỏng độc lập, chưa tính cap/vốn đồng thời.\n\nĐã xác minh SHA256 nguồn, tái tính318áp lực bán từ nến raw, đối chiếu danh sách từng ngưỡng, nested subsets, bins, win/ROE/stress, mẫu số quét, các giao volume và thời gian. Tập nguồn đã kiểm tra độc lập PnL/quét/không dùng tương lai. Không kéo lại giá hoặc snapshot hiện tại vào lịch sử.\n\nKhông cập nhật runtime, Binance, entry/size/leverage/SL/TP, Discord, gate, WHITELIST hoặc WebPush. Không thêm card giao dịch và không reset state/history/cooldown. JSON cũ không sửa; dữ liệu phân tích versioned trong thư mục riêng.\n';
await fs.writeFile(d+'/BAO_CAO.md',md);console.log('REPORT_WRITTEN');

